/**
 * Plan-limit enforcement on the write paths.
 *
 * `PLAN_LIMITS` is the single source of the numbers and `wouldExceedLimit()`
 * the single comparison; these cases prove the services actually consult them
 * before writing, and that a pending invitation already holds its seat.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
// The only double left in this suite. `@/lib/rate-limit` is real everywhere
// else, but these cases need to *choose* the verdict — the seat-quota refusal
// has to be provably about seats and not about a bucket the previous case
// happened to drain, and the throttling case needs a guaranteed denial.
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { getPlanLimits } from "@/config/plan-limits";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as usageService from "@/server/services/usage-service";
import { rateLimitState } from "./_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
/** Free plan: 3 seats, 2 projects. The fixture seeds four members. */
let free: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  free = await createTenant("frugal", "free");
  growth = await createTenant("growing", "growth");
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

describe("seat quota on invite", () => {
  it("rejects an invite once the plan's seats are taken", async () => {
    expect(getPlanLimits("free").seats).toBe(3);
    await expect(memberRepo.countActiveMembers(free.org.id)).resolves.toBe(4);

    await expect(
      invitationService.inviteMember(free.actors.owner, {
        orgId: free.org.id,
        email: "fifth@frugal.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
  });

  it("writes no invitation row when the quota rejects the batch", async () => {
    await expect(
      invitationRepo.countPendingInvitations(free.org.id),
    ).resolves.toBe(0);
  });

  it("rejects a bulk invite as a whole rather than partially filling it", async () => {
    const limits = getPlanLimits("growth");
    expect(limits.seats).toBe(50);

    const invites = Array.from({ length: 49 }, (_, index) => ({
      email: `bulk-${index}@growing.test`,
      role: "member" as const,
    }));

    await expect(
      invitationService.inviteMembers(growth.actors.owner, {
        orgId: growth.org.id,
        invites,
      }),
    ).rejects.toThrow(/seats/i);

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(0);
  });

  it("counts a pending invitation against the seat quota", async () => {
    const before = await invitationRepo.countPendingInvitations(growth.org.id);

    await invitationService.inviteMember(growth.actors.owner, {
      orgId: growth.org.id,
      email: "solo@growing.test",
      role: "member",
    });

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(before + 1);
  });

  it("refuses the invite when the rate limiter says no", async () => {
    rateLimitState.allowed = false;

    await expect(
      invitationService.inviteMember(growth.actors.owner, {
        orgId: growth.org.id,
        email: "throttled@growing.test",
        role: "member",
      }),
    ).rejects.toThrow(/rate limit/i);

    rateLimitState.allowed = true;
  });
});

describe("project quota", () => {
  it("rejects the project that would exceed the plan", async () => {
    expect(getPlanLimits("free").projects).toBe(2);

    // The fixture already created one project; this fills the plan.
    await projectService.createProject(free.actors.owner, {
      orgId: free.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await expect(
      projectService.createProject(free.actors.owner, {
        orgId: free.org.id,
        name: "Third",
        slug: "third",
        key: "THR",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toThrow(/projects/i);
  });
});

describe("BillingService.checkLimit", () => {
  it("reports the plan, the usage and whether one more would breach", async () => {
    await usageService.recomputeUsage(free.org.id);

    const check = await billingService.checkLimit(free.org.id, "seats");

    expect(check).toMatchObject({
      resource: "seats",
      plan: "free",
      limit: 3,
      used: 4,
      remaining: 0,
      exceeded: true,
    });
  });

  it("leaves an org with room under its limit", async () => {
    await usageService.recomputeUsage(growth.org.id);

    const check = await billingService.checkLimit(growth.org.id, "seats");
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBeGreaterThan(0);
  });
});
/**
 * Domain events published by the service layer.
 *
 * Services stay decoupled from notifications, search, the audit log and
 * webhooks by announcing facts on the bus. If an event stops firing — or fires
 * with the wrong payload — every one of those concerns silently stops working,
 * which is why the contract is pinned here rather than through its consumers.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("events");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("issue.created", () => {
  it("is emitted once per created issue, carrying the actor and the issue", async () => {
    const seen = capture("issue.created");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Emit me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      title: "Emit me",
      assigneeId: tenant.userIds.admin,
      priority: "none",
    });
    expect(seen[0]?.occurredAt).toEqual(expect.any(String));
  });

  it("is not emitted when the create is rejected", async () => {
    const seen = capture("issue.created");

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).rejects.toThrow();

    expect(seen).toHaveLength(0);
  });
});

describe("issue.status_changed", () => {
  it("carries both ends of the transition", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Move me" }),
    );

    const seen = capture("issue.status_changed");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ from: "backlog", to: "in_progress" });
  });

  it("stays silent when the status did not actually move", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "No-op move" }),
    );

    const seen = capture("issue.status_changed");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "backlog",
    });

    expect(seen).toHaveLength(0);
  });
});

describe("issue.assigned", () => {
  it("reports the previous assignee alongside the new one", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Reassign me",
        assigneeId: tenant.userIds.member,
      }),
    );

    const seen = capture("issue.assigned");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      previousAssigneeId: tenant.userIds.member,
      assigneeId: tenant.userIds.admin,
    });
  });

  it("falls back to issue.updated when the issue is un-assigned", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Unassign me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["assigneeId"]);
  });
});

describe("comment.created", () => {
  it("carries the mentions resolved server-side", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss me" }),
    );

    const seen = capture("comment.created");
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
