 */
export async function findActiveMemberUserIdsByEmail(
  orgId: OrgId,
  emails: readonly string[],
): Promise<ReadonlyMap<string, UserId>> {
  const wanted = [...new Set(emails.map((email) => email.toLowerCase()))];
  if (wanted.length === 0) return new Map();

  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
        inArray(sql`lower(${users.email})`, wanted),
      ),
    )
    .all();

  return new Map(
    rows.map((row) => [row.email.toLowerCase(), brandId<UserId>(row.userId)]),
  );
}

