/**
 * Bulk-import bookkeeping: the per-org import keys, and the one transaction
 * that writes an import's labels, issues and key together.
 */
import { and, eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, parseJsonArray } from "./_mappers";
import { highestIssueNumber } from "./issue-repository";
import type { IssueImportRow } from "@/server/db";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

/** A completed import: which issues its key produced, in file order. */
export interface IssueImportRecord {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly issueIds: readonly IssueId[];
  readonly importedBy: UserId;
  readonly createdAt: IsoTimestamp;
}

/** One row ready to write, its assignee already resolved to a member. */
export interface ImportedIssueDraft {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Exact label names; one that does not exist yet in the org is created. */
  readonly labelNames: readonly string[];
}

export interface NewIssueImport {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly importedBy: UserId;
  readonly rows: readonly ImportedIssueDraft[];
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toImportRecord(row) : null;
}

/**
 * Writes a whole import or nothing: the labels it names that the org lacks,
 * the issues numbered in row order after the project's highest number, their
 * label links and the import key. When the key turns out to have been
 * committed in the meantime nothing is written and that earlier record comes
 * back with `created: false`.
 */
export async function insertImport(
  input: NewIssueImport,
): Promise<{ record: IssueImportRecord; created: boolean }> {
  return getDb().transaction((tx) => {
    const existing = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (existing) return { record: toImportRecord(existing), created: false };

    const stamp = toIsoTimestamp(new Date());

    const names = [...new Set(input.rows.flatMap((row) => row.labelNames))];
    const labelIdByName = new Map<string, LabelId>();

    if (names.length > 0) {
      const found = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(
          and(orgPredicate(labels.orgId, input.orgId), inArray(labels.name, names)),
        )
        .all();
      for (const label of found) {
        labelIdByName.set(label.name, brandId<LabelId>(label.id));
      }
    }

    for (const name of names) {
      if (labelIdByName.has(name)) continue;
      // Colour is left to the column default; imported labels carry no description.
      const created = tx
        .insert(labels)
        .values({
          id: newId(),
          orgId: input.orgId,
          name,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning({ id: labels.id })
        .get();
      labelIdByName.set(name, brandId<LabelId>(created.id));
    }

    let number = highestIssueNumber(tx, input.orgId, input.projectId);
    const issueIds: IssueId[] = [];

    for (const row of input.rows) {
      number += 1;
      const issueId = brandId<IssueId>(newId());

      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.importedBy,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      const labelIds = [...new Set(row.labelNames)].map(
        (name) => labelIdByName.get(name) as LabelId,
      );
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({ orgId: input.orgId, issueId, labelId })),
          )
          .run();
      }

      issueIds.push(issueId);
    }

    const record = tx
      .insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        issueIds: JSON.stringify(issueIds),
        importedBy: input.importedBy,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return { record: toImportRecord(record), created: true };
  });
}

function toImportRecord(row: IssueImportRow): IssueImportRecord {
  return {
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    importKey: row.importKey,
    issueIds: parseJsonArray<string>(row.issueIds).map((id) =>
      brandId<IssueId>(id),
    ),
    importedBy: brandId<UserId>(row.importedBy),
    createdAt: brandStamp(row.createdAt),
  };
}

