import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

/** Token bucket for issue writes; an import spends one token per row. */
const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  await assertProjectHasRoom(project, 1);

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
  return issue;
}

/**
 * Bulk import: every row becomes an issue in the project, in file order, or —
 * when any gate refuses — nothing is written at all. The gates are those of
 * `createIssue` plus the quota and rate allowance for the whole batch; only
 * the persisted import record makes the key count as used, so a refused
 * upload can be retried under the same key. A key the org has already
 * imported replays that first result instead of importing again.
 *
 * Publishes a single `issues.imported` rather than one `issue.created` per
 * row, so the per-issue fan-out (notifications, webhooks, audit rows) stays
 * quiet while search, usage and the audit log react to the batch.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const previous = await issueImportRepo.findImport(
    input.orgId,
    input.importKey,
  );
  if (previous !== null) return importResult(previous, true);

  await assertProjectHasRoom(project, input.rows.length);

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  // Rows normally arrive parsed by `importIssuesSchema`; the optional
  // fields are defaulted again so an unparsed row cannot break the lookups.
  const assignees = await memberRepo.findActiveMemberUserIdsByEmail(
    input.orgId,
    input.rows.flatMap((row) => (row.assigneeEmail ? [row.assigneeEmail] : [])),
  );

  const { record, created } = await issueImportRepo.insertImport({
    orgId: input.orgId,
    projectId: project.id,
    importKey: input.importKey,
    importedBy: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description ?? null,
      status: row.status ?? "backlog",
      priority: row.priority ?? "none",
      assigneeId: row.assigneeEmail
        ? (assignees.get(row.assigneeEmail.toLowerCase()) ?? null)
        : null,
      dueAt: row.dueAt ?? null,
      labelNames: row.labels ?? [],
    })),
  });
  if (!created) return importResult(record, true);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: record.projectId,
    importKey: record.importKey,
    issueIds: record.issueIds,
  });

  return importResult(record, false);
}

